import { ArrowRight } from 'lucide-react';
import BlogLayout from '../components/BlogLayout';
import ArticleCard from '../components/ArticleCard';
import { posts, guides } from '../content';

export default function BlogIndex() {
  const withImage = posts.filter((p) => p.card);
  const textOnly = posts.filter((p) => !p.card);

  return (
    <BlogLayout
      title="XeOS: External Display Browser Blog"
      description="Articles and step-by-step guides for getting the most out of your iPhone or iPad on an external monitor, TV or portable display."
      readTime={null}
      section="blog"
      isIndex
      wide
    >
      {/* Articles */}
      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5">
        {withImage.map((a) => <ArticleCard key={a.slug} article={a} />)}
      </div>

      {textOnly.length > 0 && (
        <div className="mt-8 grid sm:grid-cols-2 gap-4">
          {textOnly.map((a) => (
            <a
              key={a.slug}
              href={a.path}
              className="group block border border-slate-200 dark:border-slate-700 rounded-xl p-5 hover:border-sky-400 dark:hover:border-sky-500 hover:shadow-md transition-all duration-200 bg-white dark:bg-slate-800"
            >
              <div className="flex items-center gap-2 mb-2 flex-wrap">
                <span className="text-[11px] font-semibold px-2.5 py-0.5 rounded-full bg-sky-100 dark:bg-sky-900/40 text-sky-700 dark:text-sky-300">{a.tag}</span>
                <span className="text-[11px] text-slate-400">{a.readTime}</span>
              </div>
              <h2 className="text-base font-bold text-slate-900 dark:text-white group-hover:text-sky-600 dark:group-hover:text-sky-400 transition-colors leading-snug mb-1.5">{a.title}</h2>
              <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed">{a.description}</p>
            </a>
          ))}
        </div>
      )}

      {/* Guides */}
      <section className="mt-14 pt-10 border-t border-slate-200 dark:border-slate-700">
        <div className="flex items-end justify-between gap-4 flex-wrap mb-6">
          <div>
            <p className="text-xs font-bold text-sky-700 dark:text-sky-300 uppercase tracking-widest mb-1.5">How to</p>
            <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Guides</h2>
          </div>
          <a href="/guides" className="inline-flex items-center gap-1.5 text-sky-700 dark:text-sky-300 text-sm font-semibold hover:underline flex-shrink-0">
            All guides <ArrowRight className="w-4 h-4" />
          </a>
        </div>
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {guides.slice(0, 6).map((g) => <ArticleCard key={g.slug} article={g} />)}
        </div>
      </section>
    </BlogLayout>
  );
}
