// Access layer for the imported content pack.
//
// Everything under src/content/articles and the manifest are generated by
// `npm run import:content` from the app repo's content/ folder, never edit them
// by hand, edit the source articles and re-run the import.
//
// The manifest is small and always bundled (indexes, cards, /inapp all need it).
// The article bodies are loaded one chunk at a time, on the route that needs them.

import manifest from './manifest.json';

const bodies = import.meta.glob('./articles/*/*.html', { query: '?raw', import: 'default' });

export const allArticles = manifest;
export const guides = manifest.filter((a) => a.type === 'guide');
export const posts = manifest.filter((a) => a.type === 'blog');

export const findArticle = (type, slug) =>
  manifest.find((a) => a.type === type && a.slug === slug) || null;

/** Slugs that render through the generic <Article> page rather than a hand-written one. */
export const importedSlugs = (type) =>
  manifest.filter((a) => a.type === type && a.imported).map((a) => a.slug);

/** Resolves to the article's HTML body, or null if that slug has no imported body. */
export function loadArticleBody(type, slug) {
  const key = `./articles/${type === 'guide' ? 'guides' : 'blog'}/${slug}.html`;
  const load = bodies[key];
  return load ? load() : Promise.resolve(null);
}
